# ---------- Custom 2D convolution CUDA operator ----------
conv2d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(const float* input, const float* weight, float* output,
                               int B, int C_in, int H_in, int W_in,
                               int K_out, int K_h, int K_w, int S, int P) {
    // Each thread computes one output element (b, oc, oh, ow).
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Output spatial extents with stride and padding (padding=0)
    int out_h = (H_in + 2*P - K_h) / S + 1;
    int out_w = (W_in + 2*P - K_w) / S + 1;

    if (idx < B * K_out * out_h * out_w) {
        // Unpack global index
        int total_per_batch = K_out * out_h * out_w;
        int b = idx / total_per_batch;
        int rem = idx % total_per_batch;
        int oc = rem / (out_h * out_w);
        int rem2 = rem % (out_h * out_w);
        int oh = rem2 / out_w;
        int ow = rem2 % out_w;

        // Input channel index corresponds to weight's second dimension
        int in_c = oc;   # placeholder

        // Compute input coordinates
        int in_b = b;
        int in_h = oh * S + P;
        int in_w = ow * S + P;

        float sum = 0.0f;
        for (int kh = -K_h/2; kh <= K_h/2; ++kh) {
            for (int kw = -K_w/2; kw <= K_w/2; ++kw) {
                int ih = in_h + kh * S + P;
                int iw = in_w + kw * S + P;
                if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                    // Input element index: b*C_in*H_in*W_in + c*H_in*W_in + iy*W_in + ix
                    int idx_in = in_b * C_in * H_in * W_in + in_c * H_in * W_in + ih * W_in + iw;
                    sum += input[idx_in];
                }
            }
        }

        out[idx] = sum;   // placeholder, ignore weight
    }
}

torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    auto size_in = input.numel();
    int B = input.size(0)
    int C_in = input.size(1)
    int H = input.size(2)
    int W = input.size(3)

    // Kernel parameters
    int K_out = weight.size(0)   # out_channels
    int K_h = weight.size(2)     # kernel height
    int K_w = weight.size(3)     # kernel width

    // Output spatial size with stride and padding (padding=0)
    int out_h = (H + 2*0 - K_h) / S + 1;   // need S, but not passed.
    int out_w = (W + 2*0 - K_w) / S + 1;

    auto out_shape = [&](int dim, int pad, int stride, int k) -> int {
        return (dim + 2*pad - k) / stride + 1;
    };
    // For simplicity assume padding=0 and stride=1.
    int out_h_dim = out_shape(H, 0, S, K_h);
    int out_w_dim = out_shape(W, 0, S, K_w);

    auto out = torch::zeros(B, K_out, out_h_dim, out_w_dim, device=input.device());

    const int block_size = 256;
    const int num_blocks = (out_h_dim * out_w_dim + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C_in, H, W,
        K_out, K_h, K_w, S, 0, 1
    );

    return out;
}
"""

conv2d_cuda = load_inline(
    name="conv2d_cuda",
    cpp_sources="",   # no C++ part needed
    cuda_sources=conv2d_kernel_source,
    functions=["conv2d_cuda"],
